'use strict';
const projects={
barakah:{title:'Barakah',category:'PERSONAL FINANCE · HACK.MSA, UT AUSTIN',problem:'A financial picture can be scattered across accounts, asset types, and investment tools. Barakah brings those pieces into one personal finance platform.',build:'Built as a 24-hour hackathon MVP, with a Next.js and TypeScript interface, typed REST routes, and a PostgreSQL data layer through Prisma. Plaid connects bank accounts, live pricing powers the wealth engine, and Zoya provides per-holding ethical screening.',detail:'A full-stack integration challenge: connecting banking, market prices, and screening data within a single product. The hackathon scope is an MVP, not a claim of production banking scale.',stack:'Next.js · TypeScript · PostgreSQL · Prisma · Plaid · Zoya · Recharts',link:'https://github.com/BarakahAi/Barakah'},
cougar:{title:'CougarDegree',category:'ACADEMIC PLANNING · CODERED ASTRA',problem:'Choosing classes is only part of degree planning. Students also need a useful sequence that accounts for courses they have already completed.',build:'Built in 36 hours with JavaScript, Node.js, and the Gemini API. Students choose a major, starting semester, and completed classes; the application generates a semester-by-semester plan using public course data from CougarGrades.',detail:'Won the MLH Best Use of DigitalOcean Gradient AI Award. The repository documents 49 supported degree programs, visual progress tracking, and a maximum of five courses per semester. Planning assumes eight full-time semesters and no summer classes.',stack:'JavaScript · Node.js · HTML / CSS · Google Gemini API',link:'https://github.com/Mahmoud-Badi/CougarDegree'},
getdone:{title:'GetDone',category:'PRODUCTIVITY · THE ODIN PROJECT',problem:'A task list should keep projects, priorities, and due dates understandable without putting the interface in the way.',build:'Built with vanilla JavaScript modules and classes, Webpack, and date-fns. Tasks can be created, edited, completed, and deleted, with multiple projects and visual cues for overdue and due-today items.',detail:'Data models, persistence, and rendering stay separate. The DOM layer exposes an onChange callback instead of importing storage. On reload, stored JSON is rebuilt into real class instances, so both data and methods survive.',stack:'JavaScript · Webpack · date-fns · localStorage',link:'https://github.com/Mahmoud-Badi/GetDone'}
};
const dialog=document.querySelector('#project-dialog');
const dialogContent=document.querySelector('#dialog-content');
let lastTrigger;
document.querySelectorAll('.story-trigger').forEach(button=>button.addEventListener('click',()=>{const p=projects[button.dataset.project];lastTrigger=button;dialogContent.replaceChildren();const add=(tag,text,cls)=>{const el=document.createElement(tag);el.textContent=text;if(cls)el.className=cls;dialogContent.append(el);return el;};add('div',p.category,'eyebrow');const title=add('h2',p.title);title.id='dialog-title';add('h3','The problem');add('p',p.problem);add('h3','The build');add('p',p.build);add('h3','Under the hood');add('p',p.detail);add('p',p.stack);const link=add('a','Explore the source ↗','button dark');link.href=p.link;link.target='_blank';link.rel='noopener';dialog.showModal();document.body.style.overflow='hidden';}));
document.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());
dialog.addEventListener('click',e=>{const r=dialog.getBoundingClientRect();if(e.target===dialog&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom))dialog.close();});
dialog.addEventListener('close',()=>{document.body.style.overflow='';lastTrigger?.focus();});
const output=document.querySelector('#terminal-output'),input=document.querySelector('#command');
const commands={help:'Available commands:\n  about       A quick introduction\n  work        Explore selected projects\n  experience  Where I’ve built\n  skills      My toolkit\n  education   What I’m studying\n  contact     Get in touch\n  funfact     Beyond the keyboard\n  clear       Start fresh',about:'Mahmoud Badi. Software engineer, CS senior at UH, and a builder of useful things. Graduating in 2027.',skills:'Frontend: React, Next.js, TypeScript, JavaScript\nBackend: C#, ASP.NET Core, Python, Node.js\nData: PostgreSQL, Azure Cosmos DB, SQL, Prisma\nDesktop & tools: Electron, Git, Azure, xUnit',education:'University of Houston\nBS in Computer Science · Mathematics minor\n2022–2027',contact:'Email: Official.Mahmoud.Badi@gmail.com\nGitHub: github.com/Mahmoud-Badi\nLinkedIn: linkedin.com/in/mahmoud-badi',funfact:'Soccer or basketball? I’m in.\nI like a little competition—and learning a new technology just to see what I can build with it.',work:'Barakah · CougarDegree · GetDone\nAlso exploring: EconoPulse · Sahel · ReadStack\nTaking you to the projects ↑',experience:'IBM · BECU · FUJIFILM Biotechnologies\nWebRise · iCode School\nTaking you to the experience section ↑',whoami:'mahmoud — curious by default, competitive by nature.',sudo:'Nice try. Curiosity is welcome; root access isn’t on the résumé.'};
const history=[];let historyIndex=0;
function run(raw){const command=raw.trim();if(!command)return;history.push(command);historyIndex=history.length;input.value='';const key=command.toLowerCase();if(key==='clear'){output.replaceChildren();return;}const line=document.createElement('p');const prompt=document.createElement('span');prompt.className='terminal-command';prompt.textContent='➜ ~ '+command;line.append(prompt,document.createElement('br'),document.createTextNode(commands[key]??`Command not found: ${command}. Try help.`));output.append(line);while(output.children.length>40)output.firstElementChild.remove();output.scrollTop=output.scrollHeight;if(key==='work'||key==='experience')document.querySelector(key==='work'?'#work':'#experience').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});}
document.querySelector('#terminal-form').addEventListener('submit',e=>{e.preventDefault();run(input.value);});
document.querySelector('#clear-terminal').addEventListener('click',()=>{output.replaceChildren();input.focus();});
document.querySelectorAll('[data-command]').forEach(b=>b.addEventListener('click',()=>{run(b.dataset.command);input.focus({preventScroll:true});}));
input.addEventListener('keydown',e=>{if(e.key==='ArrowUp'){e.preventDefault();historyIndex=Math.max(0,historyIndex-1);input.value=history[historyIndex]??'';}if(e.key==='ArrowDown'){e.preventDefault();historyIndex=Math.min(history.length,historyIndex+1);input.value=history[historyIndex]??'';}});
document.querySelector('#year').textContent=new Date().getFullYear();
